const q=new URLSearchParams(location.search),page=document.body.dataset.page,el=s=>document.querySelector(s);
const date=v=>new Intl.DateTimeFormat('pt-BR',{dateStyle:'medium'}).format(new Date(`${v}T12:00:00`));
const time=v=>new Intl.DateTimeFormat('pt-BR',{timeZone:'America/Sao_Paulo',dateStyle:'short',timeStyle:'short'}).format(new Date(v));
const crest=(url,name)=>url?`<img class="crest" src="${url}" alt="Brasão do ${name}" loading="lazy">`:'';
const club=(name,url)=>`<span class="club">${crest(url,name)}${name}</span>`;
const shell=(title,kicker='Série A · Brasil')=>`<header class="top"><div class="wrap"><a class="brand" href="index.html"><span class="mark">↗</span>FUTRanking</a><nav><a href="ranking.html">Ranking</a><a href="resultados.html">Resultados</a><a href="proximos-jogos.html">Próximos jogos</a><a href="metodo.html">Método</a></nav><span class="pill">${kicker}</span></div></header><main class="wrap page"><div class="eyebrow">${kicker}</div><h1>${title}</h1><div id="content"></div></main><footer class="foot"><div class="wrap">FUTRanking · Glicko-2 para o futebol brasileiro</div></footer>`;
function game(m,fixture=false){const score=fixture?`<span class="score forecast">${m.home_favoritism}% · ${m.away_favoritism}%</span>`:`<span class="score">${m.home_goals}–${m.away_goals}</span>`;const hm=fixture?`Rating ${m.home_rating.toFixed(1)} · favoritismo ${m.home_favoritism}%`:`Rating ${m.home_rating_after?.toFixed(1)??'—'} · impacto ${m.home_rating_effect>=0?'+':''}${m.home_rating_effect?.toFixed(1)??'—'}`;const am=fixture?`Rating ${m.away_rating.toFixed(1)} · favoritismo ${m.away_favoritism}%`:`Rating ${m.away_rating_after?.toFixed(1)??'—'} · impacto ${m.away_rating_effect>=0?'+':''}${m.away_rating_effect?.toFixed(1)??'—'}`;return `<article class="row"><span class="date">${fixture?time(m.scheduled_at):date(m.played_at)}</span><span class="home">${club(m.home_team,m.home_crest)}<small class="rating">${hm}</small></span>${score}<span class="away">${club(m.away_team,m.away_crest)}<small class="rating">${am}</small></span></article>`}
function method(){document.body.innerHTML=shell('Método','Como funciona');el('#content').innerHTML=`<div class="prose"><p>O FUTRanking usa o <strong>Glicko-2</strong> para estimar a força atual dos clubes. Não mede “pontos de tabela”: a cada jogo ele compara o resultado observado com o resultado esperado, levando em conta a incerteza de ambos os times.</p><h2>Hipóteses do modelo</h2><ol><li>Um clube novo começa em <strong>r = 1500</strong>, <strong>RD = 350</strong> e volatilidade <strong>σ = 0,06</strong>.</li><li>O período de atualização é uma <strong>semana</strong>. Todas as partidas da semana usam os ratings do seu início e são calculadas juntas; a ordem em que os jogos são listados não altera o resultado.</li><li>O placar é convertido em <strong>s = 1</strong> para vitória, <strong>0,5</strong> para empate e <strong>0</strong> para derrota.</li><li>O mandante recebe <strong>55 pontos de rating</strong> apenas no cálculo da expectativa pré-jogo. Esse bônus não é somado ao rating exibido do clube.</li><li>Sem jogos, o rating não muda, mas a incerteza (RD) cresce. Assim, uma equipe muito tempo sem jogar é tratada com menos certeza.</li></ol><h2>Escala interna</h2><p>O Glicko-2 trabalha numa escala própria. Para cada clube, convertemos rating e incerteza com <span class="formula">μ = (r − 1500) / 173,7178</span> e <span class="formula">φ = RD / 173,7178</span>. Ao final, voltamos com <span class="formula">r = 1500 + 173,7178μ</span> e <span class="formula">RD = 173,7178φ</span>.</p><h2>Expectativa antes do jogo</h2><p>A incerteza do adversário reduz o peso da comparação: <span class="formula">g(φⱼ) = 1 / √(1 + 3φⱼ²/π²)</span>. A expectativa de pontuação do clube <em>i</em> contra <em>j</em> é:</p><p class="formula block">Eᵢⱼ = 1 / [1 + exp(−g(φⱼ) · (μᵢ + h/173,7178 − μⱼ))]</p><p>Aqui, <strong>h = +55</strong> para o mandante e <strong>h = −55</strong> para o visitante. Nos fixtures, o “favoritismo” exibido é essa expectativa de Glicko-2 em porcentagem. Ele é uma medida de força relativa com mando, não um mercado de odds nem uma previsão explícita de placar.</p><h2>Atualização semanal</h2><p>Para todos os jogos da semana, primeiro calculamos a variância <span class="formula">v = [Σ g(φⱼ)²Eᵢⱼ(1−Eᵢⱼ)]⁻¹</span> e a surpresa agregada <span class="formula">Δ = v · Σ g(φⱼ)(sᵢⱼ−Eᵢⱼ)</span>. Ganhar acima do esperado torna Δ positivo; perder um jogo em que se era favorito tende a torná-lo negativo.</p><p>A volatilidade nova σ′ é obtida numericamente pela equação oficial do Glicko-2, com <strong>τ = 0,5</strong> e <span class="formula">a = ln(σ²)</span>:</p><p class="formula block">f(x) = eˣ(Δ²−φ²−v−eˣ) / [2(φ²+v+eˣ)²] − (x−a)/τ² = 0, &nbsp; σ′ = eˣ⁄²</p><p>Com σ′, a atualização é <span class="formula">φ* = √(φ²+σ′²)</span>, <span class="formula">φ′ = [1/φ*² + 1/v]⁻½</span> e <span class="formula">μ′ = μ + φ′²Σg(φⱼ)(sᵢⱼ−Eᵢⱼ)</span>. Depois os valores são convertidos de volta para rating e RD.</p><h2>Como ler o “impacto” de uma partida</h2><p>O impacto exibido nos resultados não atualiza jogos em sequência. Ele é calculado como <span class="formula">rating da semana completa − rating da mesma semana sem aquela partida</span>. Isso mostra a contribuição marginal daquele jogo sem inventar uma ordem entre partidas simultâneas. Por isso, os impactos de uma semana não precisam somar exatamente à mudança total do rating.</p><h2>Dados e limites</h2><p>Resultados, agenda e brasões vêm do football-data.org. Só partidas finalizadas alteram o ranking; fixtures são apenas projeções. O escopo atual é a Série A brasileira e o desempenho no perfil de cada clube considera as partidas já importadas no banco.</p></div>`}
fetch('./data/ranking.json').then(r=>r.json()).then(data=>{if(page==='ranking'){document.body.innerHTML=shell('Ranking');el('#content').innerHTML=`<p>Força estimada, atualizada até ${date(data.period_date)}. Clique em um clube.</p><section class="panel">${data.teams.map(t=>`<a class="row rank" href="clube.html?time=${encodeURIComponent(t.name)}"><span>${t.position}º</span><b>${club(t.name,t.crest)}</b><strong>${t.rating.toFixed(1)}</strong><span>RD ${t.rd.toFixed(1)}</span></a>`).join('')}</section>`}if(page==='resultados'){document.body.innerHTML=shell('Últimos resultados','Transparência');el('#content').innerHTML=`<p>Rating após o ciclo e impacto estimado daquele jogo.</p><section class="panel">${data.matches.slice(0,30).map(m=>game(m)).join('')}</section>`}if(page==='fixtures'){document.body.innerHTML=shell('Próximos jogos','Agenda');el('#content').innerHTML=`<p>Horários em Brasília. Percentuais representam favoritismo Glicko-2 com mando de campo.</p><section class="panel">${data.fixtures.map(m=>game(m,true)).join('')||'<p style="padding:20px">Nenhum jogo futuro disponível.</p>'}</section>`}if(page==='club'){const name=q.get('time'),team=data.teams.find(t=>t.name===name);if(!team){document.body.innerHTML=shell('Clube não encontrado');return}const matches=data.matches.filter(m=>m.home_team===name||m.away_team===name).slice(0,12),fixtures=data.fixtures.filter(m=>m.home_team===name||m.away_team===name),p=team.performance;document.body.innerHTML=shell(club(name,team.crest),'Perfil do clube');el('#content').innerHTML=`<a class="back" href="ranking.html">← Voltar ao ranking</a><div class="stats"><div class="stat"><b>${team.position}º</b><span>posição</span></div><div class="stat"><b>${team.rating.toFixed(1)}</b><span>rating</span></div><div class="stat"><b>${p.games}</b><span>jogos</span></div><div class="stat"><b>${p.wins}-${p.draws}-${p.losses}</b><span>V-E-D</span></div><div class="stat"><b>${p.goals_for}:${p.goals_against}</b><span>gols</span></div><div class="stat"><b>${p.points}</b><span>pontos</span></div></div><h2>Próximos fixtures</h2><section class="panel">${fixtures.map(m=>game(m,true)).join('')||'<p style="padding:20px">Nenhum fixture futuro disponível.</p>'}</section><h2>Últimos resultados</h2><section class="panel">${matches.map(m=>game(m)).join('')}</section>`}if(page==='method')method()}).catch(()=>document.body.innerHTML=shell('Dados indisponíveis'));

